// src/components/Entrenador/ControlPagos.js
import React, { useState, useEffect } from 'react';
import { 
  getJugadores, getPagosPendientes, getEntrenamientos, getPartidos,
  pagarPagoPendiente
} from '../../database/db';
import './ControlPagos.css';

function ControlPagos() {
  const [jugadores, setJugadores] = useState([]);
  const [pagos, setPagos] = useState([]);
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [partidos, setPartidos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filtroJugador, setFiltroJugador] = useState('');
  const [filtroEstado, setFiltroEstado] = useState('todos');
  const [jugadorSeleccionado, setJugadorSeleccionado] = useState(null);
  const [mostrarDetalle, setMostrarDetalle] = useState(false);
  const [refrescar, setRefrescar] = useState(false);

  useEffect(() => {
    cargarDatos();
  }, [refrescar]);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [jugadoresData, pagosData, entrenamientosData, partidosData] = await Promise.all([
        getJugadores(),
        getPagosPendientes(),
        getEntrenamientos(),
        getPartidos()
      ]);
      setJugadores(jugadoresData);
      setPagos(pagosData);
      setEntrenamientos(entrenamientosData);
      setPartidos(partidosData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const refrescarDatos = () => {
    setRefrescar(!refrescar);
  };

  const getDeudaPorJugador = (jugadorId) => {
    const pagosJugador = pagos.filter(p => p.jugador_id === jugadorId && p.estado === 'pendiente');
    return pagosJugador.reduce((total, p) => total + (p.monto || 0), 0);
  };

  const getDetallesPagosPendientes = (jugadorId) => {
    return pagos
      .filter(p => p.jugador_id === jugadorId && p.estado === 'pendiente')
      .map(pago => {
        let eventoNombre = '';
        if (pago.evento_tipo === 'entrenamiento') {
          const evento = entrenamientos.find(e => e.id === pago.evento_id);
          eventoNombre = evento ? `Entrenamiento del ${new Date(evento.fecha).toLocaleDateString()}` : 'Entrenamiento';
        } else if (pago.evento_tipo === 'partido') {
          const evento = partidos.find(p => p.id === pago.evento_id);
          eventoNombre = evento ? `Partido vs ${evento.rival} - ${new Date(evento.fecha).toLocaleDateString()}` : 'Partido';
        }
        return { ...pago, eventoNombre };
      })
      .sort((a, b) => new Date(b.fecha_creacion) - new Date(a.fecha_creacion));
  };

  const getPagosRealizados = (jugadorId) => {
    return pagos
      .filter(p => p.jugador_id === jugadorId && p.estado === 'pagado')
      .sort((a, b) => new Date(b.fecha_pago) - new Date(a.fecha_pago));
  };

  const handleRegistrarPago = async (pagoId, monto, eventoNombre, jugadorNombre) => {
    if (window.confirm(`¿Confirmar pago de $${monto} por concepto de ${eventoNombre} para ${jugadorNombre}?`)) {
      try {
        await pagarPagoPendiente(pagoId, 'manual');
        await cargarDatos();
        alert(`✅ Pago de $${monto} registrado correctamente`);
      } catch (error) {
        alert('Error al registrar el pago: ' + error.message);
      }
    }
  };

  const handlePagarTodos = async (jugadorId, jugadorNombre, deudaTotal) => {
    if (deudaTotal === 0) {
      alert('⚠️ Este jugador no tiene deuda pendiente');
      return;
    }
    
    if (window.confirm(`¿Confirmar pago de TODOS los pagos pendientes ($${deudaTotal}) para ${jugadorNombre}?`)) {
      try {
        const pagosPendientes = pagos.filter(p => p.jugador_id === jugadorId && p.estado === 'pendiente');
        for (const pago of pagosPendientes) {
          await pagarPagoPendiente(pago.id, 'manual');
        }
        await cargarDatos();
        alert(`✅ Todos los pagos de ${jugadorNombre} han sido registrados. Total: $${deudaTotal}`);
      } catch (error) {
        alert('Error al registrar los pagos: ' + error.message);
      }
    }
  };

  const verDetalle = (jugador) => {
    setJugadorSeleccionado(jugador);
    setMostrarDetalle(true);
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return 'Fecha no disponible';
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });
      }
      return fecha;
    } catch (e) {
      return 'Fecha inválida';
    }
  };

  const totalJugadores = jugadores.length;
  const jugadoresConDeuda = jugadores.filter(j => getDeudaPorJugador(j.id) > 0).length;
  const totalDeudaGeneral = jugadores.reduce((total, j) => total + getDeudaPorJugador(j.id), 0);
  const totalPagosRegistrados = pagos.filter(p => p.estado === 'pagado').length;

  const jugadoresFiltrados = jugadores.filter(j => {
    const nombreMatch = j.nombre.toLowerCase().includes(filtroJugador.toLowerCase());
    const deuda = getDeudaPorJugador(j.id);
    if (filtroEstado === 'con-deuda') return nombreMatch && deuda > 0;
    if (filtroEstado === 'sin-deuda') return nombreMatch && deuda === 0;
    return nombreMatch;
  });

  if (loading) {
    return (
      <div className="control-pagos">
        <div className="loading-container">
          <i className="fas fa-spinner fa-spin"></i>
          <p>Cargando datos de pagos...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="control-pagos">
      <div className="header-actions">
        <h2><i className="fas fa-dollar-sign"></i> Control de Pagos</h2>
        <button className="btn-refrescar" onClick={refrescarDatos}>
          <i className="fas fa-sync-alt"></i> Refrescar
        </button>
      </div>

      <div className="stats-resumen">
        <div className="resumen-card">
          <i className="fas fa-users"></i>
          <div>
            <h3>{totalJugadores}</h3>
            <p>Total Jugadores</p>
          </div>
        </div>
        <div className="resumen-card warning">
          <i className="fas fa-exclamation-triangle"></i>
          <div>
            <h3>{jugadoresConDeuda}</h3>
            <p>Con Deuda</p>
          </div>
        </div>
        <div className="resumen-card success">
          <i className="fas fa-check-circle"></i>
          <div>
            <h3>{totalPagosRegistrados}</h3>
            <p>Pagos Registrados</p>
          </div>
        </div>
        <div className="resumen-card primary">
          <i className="fas fa-dollar-sign"></i>
          <div>
            <h3>${totalDeudaGeneral.toLocaleString()}</h3>
            <p>Deuda Total</p>
          </div>
        </div>
      </div>

      <div className="filtros">
        <div className="filtro-busqueda">
          <i className="fas fa-search"></i>
          <input 
            type="text" 
            placeholder="Buscar jugador por nombre..." 
            value={filtroJugador}
            onChange={(e) => setFiltroJugador(e.target.value)}
          />
        </div>
        <div className="filtro-estado">
          <button className={filtroEstado === 'todos' ? 'active' : ''} onClick={() => setFiltroEstado('todos')}>
            Todos
          </button>
          <button className={filtroEstado === 'con-deuda' ? 'active' : ''} onClick={() => setFiltroEstado('con-deuda')}>
            Con Deuda
          </button>
          <button className={filtroEstado === 'sin-deuda' ? 'active' : ''} onClick={() => setFiltroEstado('sin-deuda')}>
            Sin Deuda
          </button>
        </div>
      </div>

      <div className="table-container">
        <table className="data-table">
          <thead>
            <tr>
              <th>#</th>
              <th>Jugador</th>
              <th>Posición</th>
              <th>Deuda Total</th>
              <th>Pagos Pendientes</th>
              <th>Acciones</th>
            </tr>
          </thead>
          <tbody>
            {jugadoresFiltrados.length === 0 ? (
              <tr>
                <td colSpan="6" className="empty-row">No se encontraron jugadores</td>
              </tr>
            ) : (
              jugadoresFiltrados.map(jugador => {
                const deuda = getDeudaPorJugador(jugador.id);
                const pagosPendientes = getDetallesPagosPendientes(jugador.id);
                
                return (
                  <tr key={jugador.id} className={deuda > 0 ? 'con-deuda' : ''}>
                    <td className="numero">{jugador.numero_camiseta || '?'}</td>
                    <td className="jugador-nombre">
                      <strong>{jugador.nombre}</strong>
                    </td>
                    <td className="posicion">{jugador.posicion || 'Sin posición'}</td>
                    <td className={`deuda ${deuda > 0 ? 'pendiente' : 'pagado'}`}>
                      ${deuda.toLocaleString()}
                    </td>
                    <td className="pagos-pendientes">
                      {pagosPendientes.length > 0 ? (
                        <span className="badge-pendiente">{pagosPendientes.length} pendiente(s)</span>
                      ) : (
                        <span className="badge-pagado">✓ Al día</span>
                      )}
                    </td>
                    <td className="acciones">
                      <button className="btn-ver" onClick={() => verDetalle(jugador)}>
                        <i className="fas fa-eye"></i> Ver
                      </button>
                      {deuda > 0 && (
                        <button className="btn-pagar" onClick={() => handlePagarTodos(jugador.id, jugador.nombre, deuda)}>
                          <i className="fas fa-dollar-sign"></i> Pagar todo
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {mostrarDetalle && jugadorSeleccionado && (
        <div className="modal-overlay" onClick={() => setMostrarDetalle(false)}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3><i className="fas fa-user"></i> Detalle de Pagos - {jugadorSeleccionado.nombre}</h3>
              <button className="close-btn" onClick={() => setMostrarDetalle(false)}>&times;</button>
            </div>
            
            <div className="detalle-pagos">
              <div className="jugador-resumen">
                <div className="info-jugador">
                  <span className="numero">#{jugadorSeleccionado.numero_camiseta || '?'}</span>
                  <span className="nombre">{jugadorSeleccionado.nombre}</span>
                  <span className="posicion">{jugadorSeleccionado.posicion || 'Sin posición'}</span>
                </div>
                <div className="deuda-total">
                  <span>Deuda total:</span>
                  <strong>${getDeudaPorJugador(jugadorSeleccionado.id).toLocaleString()}</strong>
                </div>
              </div>

              <div className="seccion-pagos">
                <h4><i className="fas fa-clock"></i> Pagos Pendientes ({getDetallesPagosPendientes(jugadorSeleccionado.id).length})</h4>
                {getDetallesPagosPendientes(jugadorSeleccionado.id).length === 0 ? (
                  <div className="no-pagos">
                    <i className="fas fa-check-circle"></i>
                    <p>No hay pagos pendientes</p>
                  </div>
                ) : (
                  <div className="pagos-list">
                    {getDetallesPagosPendientes(jugadorSeleccionado.id).map(pago => (
                      <div key={pago.id} className="pago-item pendiente">
                        <div className="pago-info">
                          <span className="concepto">
                            {pago.evento_tipo === 'entrenamiento' ? '🏃 Entrenamiento' : '🏆 Partido'}
                          </span>
                          <span className="fecha">{formatearFecha(pago.fecha_creacion)}</span>
                          <span className="monto">${pago.monto}</span>
                        </div>
                        <button 
                          className="btn-registrar-pago"
                          onClick={() => handleRegistrarPago(pago.id, pago.monto, pago.eventoNombre, jugadorSeleccionado.nombre)}
                        >
                          <i className="fas fa-check"></i> Registrar pago
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              {getPagosRealizados(jugadorSeleccionado.id).length > 0 && (
                <div className="seccion-pagos">
                  <h4><i className="fas fa-history"></i> Historial de Pagos</h4>
                  <div className="pagos-list">
                    {getPagosRealizados(jugadorSeleccionado.id).map(pago => (
                      <div key={pago.id} className="pago-item pagado">
                        <div className="pago-info">
                          <span className="concepto">
                            {pago.evento_tipo === 'entrenamiento' ? '🏃 Entrenamiento' : '🏆 Partido'}
                          </span>
                          <span className="fecha">{formatearFecha(pago.fecha_creacion)}</span>
                          <span className="monto">${pago.monto}</span>
                          <span className="metodo">{pago.metodo_pago === 'qr' ? '📱 QR' : '💵 Manual'}</span>
                          <span className="fecha-pago">{pago.fecha_pago ? new Date(pago.fecha_pago).toLocaleDateString() : ''}</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="modal-footer">
              <button className="btn-cerrar" onClick={() => setMostrarDetalle(false)}>Cerrar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ControlPagos;
